// src/lib/store.ts

export interface ProductItem {
  id: string;
  sku: string;
  barcode: string;
  name: string;
  brand?: string;
  gender?: string; // Caballero, Dama, Unisex
  category: string;
  unit: string; // Onza, Unidad, Paquete, Galón
  price: number;
  cost: number;
  stock: number;
  minStock: number;
  imageUrl: string;
  isAvailableOnline: boolean;
  puesto?: string; // Ubicación física en estante (Ej: A1 = Estante A, Nivel 1)
}

export interface CartItem {
  product: ProductItem;
  quantity: number;
}

export interface SaleRecord {
  id: string;
  saleNumber: string;
  createdAt: string;
  total: number;
  subtotal: number;
  ivaTotal: number;
  paymentMethod: 'CASH' | 'CARD' | 'TRANSFER' | 'BITCOIN';
  cashReceived?: number;
  cashChange?: number;
  tipoComprobante: 'TICKET' | '01' | '03';
  cliente: {
    nombre: string;
    numDocumento?: string;
    nrc?: string;
    correo?: string;
    direccion?: string;
  };
  dteInfo?: {
    codigoGeneracion?: string;
    numeroControl?: string;
    selloRecepcion?: string;
    estado?: string;
    simulated?: boolean;
    mensaje?: string;
  };
  status?: 'PENDING_PREPARATION' | 'READY_AT_WINDOW' | 'COMPLETED' | 'CANCELLED';
  vendedor?: string;
  items: {
    productId: string;
    name: string;
    quantity: number;
    price: number;
    total: number;
    unit?: string;
    puesto?: string;
  }[];
}

